#include "common.hpp"
#include "cartridge.hpp"
#include <set>
namespace {
std::vector<NcmContentMetaKey> keys(NcmContentMetaDatabase&db){NcmContentMetaKey rows[256]{};s32 total=0,n=0;check(ncmContentMetaDatabaseList(&db,&total,&n,rows,256,NcmContentMetaType_Application,0,0,UINT64_MAX,NcmContentInstallType_Full),"Cartridge title list");require(n>=0&&n<=256&&total==n,"Cartridge title list incomplete");return {rows,rows+n};}
std::string path(NcmContentStorage&cs,const NcmContentId&id){char out[FS_MAX_PATH]{};check(ncmContentStorageGetPath(&cs,out,sizeof(out),&id),"Cartridge content path");require(memchr(out,0,sizeof(out))&&std::string(out).rfind("@Gc",0)==0,"Content no longer belongs to inserted cartridge");return out;}
}
std::vector<uint64_t> cartridgeTitles(){std::vector<uint64_t>out;Result rc=ncmInitialize();if(R_FAILED(rc))return out;struct End{~End(){ncmExit();}}end;MetaDb db;if(R_FAILED(ncmOpenContentMetaDatabase(&db.db,NcmStorageId_GameCard)))return out;for(const auto&k:keys(db.db))if(k.id&&!(k.id&0xfff))out.push_back(k.id);std::sort(out.begin(),out.end());out.erase(std::unique(out.begin(),out.end()),out.end());return out;}
void backupCartridge(uint64_t title,const std::string&directory){
 closed(title);check(ncmInitialize(),"Cartridge NCM");struct End{~End(){ncmExit();}}end;MetaDb db;Storage cs;check(ncmOpenContentMetaDatabase(&db.db,NcmStorageId_GameCard),"Open inserted cartridge database");check(ncmOpenContentStorage(&cs.cs,NcmStorageId_GameCard),"Open inserted cartridge storage");
 auto list=keys(db.db);NcmContentMetaKey key{};unsigned matches=0;for(const auto&k:list)if(k.id==title){key=k;++matches;}require(matches==1,"Inserted cartridge changed or has ambiguous base versions");
 u64 size=0,got=0;check(ncmContentMetaDatabaseGetSize(&db.db,&size,&key),"Card metadata size");require(size&&size<=1024*1024,"Card metadata bounds");std::vector<u8>metadata(size);check(ncmContentMetaDatabaseGet(&db.db,&key,&got,metadata.data(),size),"Card metadata");require(got==size,"Card metadata truncated");
 NcmContentInfo items[256]{};s32 count=0;check(ncmContentMetaDatabaseListContentInfo(&db.db,&count,items,256,&key,0),"Card archives");require(count>0&&count<256,"Card archive count unsupported");u64 needed=16*1024*1024;std::set<std::string>ids;std::vector<std::string>paths;
 for(int i=0;i<count;++i){u64 bytes=0;ncmContentInfoSizeToU64(&items[i],&bytes);require(bytes&&bytes<=1ULL<<40&&UINT64_MAX-needed>=bytes,"Card archive size invalid");needed+=bytes;require(ids.insert(hex((u8*)&items[i].content_id,16)).second,"Duplicate card archive");paths.push_back(path(cs.cs,items[i].content_id));}
 FsFileSystem sd{};check(fsOpenSdCardFileSystem(&sd),"SD capacity");s64 free=0;auto rc=fsFsGetFreeSpace(&sd,"/",&free);fsFsClose(&sd);check(rc,"SD free space");require(free>=0&&(u64)free>=needed,"Insufficient SD space for cartridge backup");
 std::string root=directory+"/cartridge";fresh(root);write(root+"/INCOMPLETE.txt","Copying cartridge",17);write(root+"/base.key.bin",&key,sizeof(key));write(root+"/base.ncm.bin",metadata.data(),metadata.size());write(root+"/base.content.bin",items,count*sizeof(items[0]));
 std::vector<u8>buffer(262144);std::string sums;for(int i=0;i<count;++i){pump();u64 bytes=0;ncmContentInfoSizeToU64(&items[i],&bytes);s64 actual=0;check(ncmContentStorageGetSizeFromContentId(&cs.cs,&actual,&items[i].content_id),"Card archive size");require(actual>0&&(u64)actual==bytes&&path(cs.cs,items[i].content_id)==paths[i],"Cartridge changed before copy");std::string name=hex((u8*)&items[i].content_id,16)+(items[i].content_type==NcmContentType_Meta?".cnmt.nca":".nca");std::string file=root+"/"+name;File out(fopen((file+".part").c_str(),"wb"),fclose);require(bool(out),"Create cartridge backup");Sha256Context hash;sha256ContextCreate(&hash);
 for(u64 off=0;off<bytes;){pump();size_t n=std::min<u64>(buffer.size(),bytes-off);check(ncmContentStorageReadContentIdFile(&cs.cs,buffer.data(),n,&items[i].content_id,off),"Read cartridge archive");require(fwrite(buffer.data(),1,n,out.get())==n,"Write cartridge backup");sha256ContextUpdate(&hash,buffer.data(),n);off+=n;vaultTransfer("Backing up cartridge base",name.c_str(),off,bytes);}flush(out.get());require(!fclose(out.release()),"Close cartridge backup");u8 digest[32];sha256ContextGetHash(&hash,digest);auto expected=hex(digest,32);require(hashFile(file+".part",bytes)==expected,"Cartridge backup checksum mismatch");require(path(cs.cs,items[i].content_id)==paths[i],"Cartridge changed during copy");require(!rename((file+".part").c_str(),file.c_str()),"Publish cartridge archive");sums+=expected+"  "+name+"\n";
 }
 std::vector<u8>after(size);check(ncmContentMetaDatabaseGet(&db.db,&key,&got,after.data(),size),"Verify cartridge metadata");require(got==size&&after==metadata,"Cartridge metadata changed");for(auto n:{"base.key.bin","base.ncm.bin","base.content.bin"}){struct stat st{};require(!stat((root+"/"+n).c_str(),&st),"Card metadata file missing");sums+=hashFile(root+"/"+n,st.st_size)+"  "+n+"\n";}write(root+"/SHA256SUMS.txt",sums.data(),sums.size());std::string info="CARTRIDGE_BACKUP_VERIFIED\ntitle="+idstr(title)+"\nbase_version="+std::to_string(key.version)+"\narchives="+std::to_string(count)+"\nOriginal cartridge archives. Not an installable digital backup.\n";require(!unlink((root+"/INCOMPLETE.txt").c_str()),"Complete cartridge backup");write(root+"/COMPLETE.txt",info.data(),info.size());note("CARTRIDGE_BACKUP_VERIFIED title=%s archives=%d path=%s\n",idstr(title).c_str(),count,root.c_str());
}
